globalThis.CognitronKnowledgePack = {"schema":"cognitron.web-knowledge-pack.v1","revision":"d19720d1a9500991b2aafcdc8f7136623de09f99","content_sha256":"05cd491e2effaafaae04c712463df9820f2b98b5380c26e430fb792cfc712cbe","source_path":"web/knowledge/public.json","source":{"schema":"cognitron.public-knowledge.v1","audience":"public","language":"tr","reviewed_on":"2026-11-12","entries":[{"id":"about","title":"Cognitron hakkında","aliases":["cognitron hakkında","cognitron nedir","kendini tanıt","about cognitron"],"summary":"Cognitron, yerel yapay zekâ ve birlikte geliştirme üzerine çalışan bir projedir. Bu sayfa projeyi tanıtır; geliştirme aşamasındaki yetenekleri tamamlanmış gibi sunmaz.","paragraphs":["Ürün bilgilerine sohbet alanından ulaşabilirsin. Açılan içerik penceresini sayfa üzerinde taşıyabilirsin.","Webdeki ziyaretçi oturumu, normal Cognitron sisteminin hafıza ve çalışma düzeninden ayrıdır."],"status":"in_development"},{"id":"status","title":"Mevcut durum ve güncellemeler","aliases":["ne değişti","güncellemeler","mevcut durum","yol haritası","son gelişmeler","nvidia"],"summary":"Web arayüzü ve sohbetten açılan içerik penceresi yerel olarak hazırlandı. Güncel ürün bilgileri sürümlü bir yayın paketine bağlanıyor; gerçek model sohbeti henüz etkin değil.","paragraphs":["Sıradaki işler: ziyaretçi gizliliğiyle uyumlu barındırma, gerçek model bağlantısı ve kamusal yayın doğrulaması.","NVIDIA için proje tanıtımı hazırlanabilir. Bu sayfa NVIDIA başvurusunun gönderildiği, kabul edildiği veya bir ortaklık kurulduğu anlamına gelmez.","GitHub'daki her değişiklik otomatik bir yetenek kazanımı değildir. Bu bilgi paketindeki doğrulanmış ürün açıklamaları güncellendiğinde web sunumu da güncellenir."],"status":"model_and_publication_pending"},{"id":"privacy","title":"Bu web oturumunun gizliliği","aliases":["gizlilik","verilerim","çerez","privacy"],"summary":"Bu sürümde yazdıkların tarayıcıdan bir sohbet servisine gönderilmez. Oturum içeriği sayfadan ayrılma veya beş dakika hareketsizlikte uygulama tarafından temizlenir.","paragraphs":["Ziyaretçi sohbetleri ürün bilgisi paketine, GitHub'a veya normal Cognitron'un kalıcı hafızasına aktarılmaz. Analitik ve oturumlar arası kişiselleştirme kullanılmaz.","Tarayıcı askıya alınırsa temizleme kodu zamanında çalışamayabilir; geri dönüşte süre denetlenir. Fiziksel bellekten geri getirilemez silme garantisi verilmez.","Barındırma sağlayıcısı güvenlik amacıyla IP adreslerini kaydedebilir. Bu istisna sohbet içeriğini kapsamaz; bu sürümde sohbet metni cihazından gönderilmez."],"status":"application_controls_only"}]}};
